CREATE VIEW public.combined_animations AS
 SELECT c.mood,
    c.animations,
    c.npc
   FROM public.animations_custom c
UNION ALL
 SELECT t.mood,
    t.animations,
    t.npc
   FROM (public.animations t
     LEFT JOIN public.animations_custom c ON (((t.mood)::text = (c.mood)::text)))
  WHERE (c.mood IS NULL);


