--
-- Name: speech_rowid_seq; Type: SEQUENCE; Schema: public; Owner: dwemer
--

CREATE SEQUENCE public.speech_rowid_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE public.speech_rowid_seq OWNER TO dwemer;

--
-- Name: speech_rowid_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: dwemer
--

ALTER SEQUENCE public.speech_rowid_seq OWNED BY public.speech.rowid;


--
-- Name: speech_view; Type: VIEW; Schema: public; Owner: dwemer
--

CREATE VIEW public.speech_view AS
 SELECT sess,
    speaker,
    speech,
    location,
    listener,
    topic,
    localts,
    gamets,
    ts,
    rowid,
    companions,
    audios,
    public.convert_gamets2skyrim_date(gamets) AS sk_date,
    public.convert_gamets2skyrim_long_date(gamets) AS sk_long_date,
    public.convert_gamets2days(gamets) AS sk_days,
    public.convert_gamets2gregorian_date(gamets) AS gregorian_date
   FROM public.speech s;


ALTER VIEW public.speech_view OWNER TO dwemer;

