INSERT INTO public.oghma VALUES ('ambrosia', 'Ambrosia is a greenish, scaly fruit that can be purchased from Khajiit caravans. Alchemy effects: Restore Health, Regenerate Health, Fortify Health, and Cure Poison.', '''alchemy'':15B ''ambrosi'':1A,2B ''and'':23B ''be'':10B ''can'':9B ''caravans'':14B ''cur'':24B ''effects'':16B ''fortify'':21B ''from'':12B ''fruit'':7B ''greenish'':5B ''health'':18B,20B,22B ''is'':3B ''khajiit'':13B ''poison'':25B ''purchas'':11B ''regenerat'':19B ''restor'':17B ''scaly'':6B ''that'':8B', 'alchemist', 'Ambrosia is a greenish, scaly fruit that can be purchased from Khajiit caravans
