INSERT INTO public.oghma VALUES ('igmund', 'Igmund is the Jarl of Markarth, a Nord barbarian who governs the city with the aid of his steward and uncle, Raerek. He is a supporter of the Imperial Legion amid the ongoing civil war in Skyrim.', '''aid'':17B ''amid'':32B ''and'':21B ''barbari'':10B ''city'':14B ''civil'':35B ''governs'':12B ''his'':19B ''igmund'':1A,2B ''imperial'':30B ''in'':37B ''is'':3B,25B ''jarl'':5B ''legion'':31B ''markarth'':7B ''nord'':9B ''of'':6B,18B,28B ''ongoing'':34B ''raerek'':23B ''skyrim'':38B ''steward'':20B ''support'':27B ''the'':4B,13B,16B,29B,33B ''uncle'':22B ''war'':36B ''who'':11B ''with'':15B', 'scholar, noble', 'Igmund is the Jarl of Markarth, a Nord barbarian, and rules with the aid of his steward and uncle, Raerek. He supports the Imperial Legion in the ongoing civil war in Skyrim.', '', '', 'figures');
