INSERT INTO public.oghma VALUES ('velvet_lechance', 'Velvet LeChance is a rich and flavorful wine created by Talen-Jei at The Bee and Barb. Its blend of honey, blackberry, and spices makes it a favorite among patrons seeking a unique drink.', '''among'':32B ''and'':8B,19B,26B ''at'':16B ''barb'':20B ''bee'':18B ''blackberry'':25B ''blend'':22B ''by'':12B ''creat'':11B ''drink'':37B ''favorit'':31B ''flavorful'':9B ''honey'':24B ''is'':5B ''it'':29B ''its'':21B ''jei'':15B ''lechanc'':2A,4B ''mak'':28B ''of'':23B ''patrons'':33B ''rich'':7B ''seeking'':34B ''spic'':27B ''tal'':14B ''talen-jei'':13B ''the'':17B ''uniqu'':36B ''velvet'':1A,3B ''win'':10B', 'talen-jei', 'You know nothing about this wine beyond hearing its name in passing.', '', '', 'items');
INSERT INTO public.oghma VALUES ('dragonstone', 'The Dragonstone  is a key artifact found in the ancient Nordic ruin of Bleak Falls Barrow. It is a large, intricately carved stone tablet that shows an ancient map that contains detailed markings of dragon burial sites across Skyrim, marking the locations where dragons are likely to appear or have appeared in the past. Given its importance it is likely to be found in the deepest sanctom of bleak falls barrow and to be protected by powerful forces.
