INSERT INTO public.oghma VALUES ('potion_of_minor_stamina', 'A simple concoction that restores a small amount of stamina, useful for light exertions and quick recovery. Restores a small amount of stamina, ideal for minor exertions and short bursts of activity. These potions can be found in random loot or purchased from alchemists.', '''activity'':36B ''alchemists'':48B ''amount'':12B,25B ''and'':19B,32B ''be'':40B ''bursts'':34B ''can'':39B ''concoction'':7B ''exertions'':18B,31B ''for'':16B,29B ''found'':41B ''from'':47B ''ideal'':28B ''in'':42B ''light'':17B ''loot'':44B ''minor'':3A,30B ''of'':2A,13B,26B,35B ''or'':45B ''potion'':1A ''potions'':38B ''purchas'':46B ''quick'':20B ''random'':43B ''recovery'':21B ''restor'':9B,22B ''short'':33B ''simpl'':6B ''small'':11B,24B ''stamin'':4A,14B,27B ''that'':8B ''thes'':37B ''useful'':15B', 'alchemist, hunter, warrior, companions, traveler', 'The Potion of Minor Stamina restores a small amount of stamina for light exertions. You do not know the full effects or details of this potion. However, an alchemist might.', '', '', 'items');
