INSERT INTO public.oghma VALUES ('flames', 'Flames is a Destruction spell that projects a continuous stream of fire, dealing fire damage to health and stamina. It requires a Novice skill level to cast.', '''and'':19B ''cast'':28B ''continuous'':10B ''damag'':16B ''dealing'':14B ''destruction'':5B ''fir'':13B,15B ''flam'':1A,2B ''health'':18B ''is'':3B ''it'':21B ''level'':26B ''novic'':24B ''of'':12B ''projects'':8B ''requir'':22B ''skill'':25B ''spell'':6B ''stamin'':20B ''stream'':11B ''that'':7B ''to'':17B,27B', 'mage', 'Flames is a spell that releases a continuous stream of fire, burning enemies and draining their health and stamina. You do not know much else about this spell.', '', '', 'spells');
