INSERT INTO public.oghma VALUES ('courage', 'Courage is an Illusion spell that boosts the target''s confidence, increasing their combat abilities and making them more likely to attack enemies. It requires an Apprentice skill level to cast.', '''abiliti'':16B ''an'':4B,27B ''and'':17B ''apprentic'':28B ''attack'':23B ''boosts'':8B ''cast'':32B ''combat'':15B ''confidenc'':12B ''courag'':1A,2B ''enemi'':24B ''illusion'':5B ''increasing'':13B ''is'':3B ''it'':25B ''level'':30B ''likely'':21B ''making'':18B ''mor'':20B ''requir'':26B ''s'':11B ''skill'':29B ''spell'':6B ''target'':10B ''that'':7B ''the'':9B,14B ''them'':19B ''to'':22B,31B', 'mage', 'Courage is a spell that boosts the target''s confidence, enhancing their combat abilities and making them more likely to attack enemies. You do not know much else about this spell.', '', '', 'spells');
