INSERT INTO public.oghma VALUES ('fortify_persuasion', 'These magical effects are utility-focused Restoration enchantments that enhance the caster;s ability to influence others in dialogue, increasing the likelihood of success in persuasion, intimidation, or bargaining. This effect is only available on enchanted gear, making it a rare boon for charismatic adventurers.', '''ability'':17B ''adventurers'':48B ''are'':6B ''avail'':37B ''bargaining'':32B ''boon'':45B ''cast'':15B ''charismatic'':47B ''dialog'':22B ''effect'':34B ''effects'':5B ''enchant'':39B ''enchantments'':11B ''enhanc'':13B ''focus'':9B ''for'':46B ''fortify'':1A ''gear'':40B ''in'':21B,28B ''increasing'':23B ''influenc'':19B ''intimidation'':30B ''is'':35B ''it'':42B ''likelihood'':25B ''magical'':4B ''making'':41B ''of'':26B ''on'':38B ''only'':36B ''or'':31B ''others'':20B ''persuasion'':2A,29B ''rar'':44B ''restoration'':10B ''s'':16B ''success'':27B ''that'':12B ''the'':14B,24B ''thes'':3B ''this'':33B ''to'':18B ''utility'':8B ''utility-focus'':7B', 'mage', 'This enchantment improves your ability to persuade or intimidate others in conversations. A mage might know more though.', '', '', 'spells');
