INSERT INTO public.oghma VALUES ('fortify_shouts', 'These magical effects are utility-focused Restoration enchantments that reduce the cooldown time of shouts, allowing the caster to use their Thu;um more frequently. This effect is only available on enchanted gear, making it a rare and valuable boon for the Dragonborn.', '''allowing'':19B ''and'':41B ''are'':6B ''avail'':33B ''boon'':43B ''cast'':21B ''cooldown'':15B ''dragonborn'':46B ''effect'':30B ''effects'':5B ''enchant'':35B ''enchantments'':11B ''focus'':9B ''for'':44B ''fortify'':1A ''frequently'':28B ''gear'':36B ''is'':31B ''it'':38B ''magical'':4B ''making'':37B ''mor'':27B ''of'':17B ''on'':34B ''only'':32B ''rar'':40B ''reduc'':13B ''restoration'':10B ''shouts'':2A,18B ''that'':12B ''the'':14B,20B,24B,45B ''thes'':3B ''this'':29B ''thu'':25B ''tim'':16B ''to'':22B ''um'':26B ''use'':23B ''utility'':8B ''utility-focus'':7B ''valuabl'':42B', 'mage', 'This enchantment reduces the time you have to wait between shouts, letting you use them more frequently. A mage might know more though.', '', '', 'spells');
INSERT INTO public.oghma VALUES ('spectral_arrow', 'Spectral Arrow is a Conjuration spell that summons a magical arrow to strike a target, dealing damage and staggering them. It requires an Adept skill level to cast.', '''adept'':26B ''an'':25B ''and'':20B ''arrow'':2A,4B,13B ''cast'':30B ''conjuration'':7B ''damag'':19B ''dealing'':18B ''is'':5B ''it'':23B ''level'':28B ''magical'':12B ''requir'':24B ''skill'':27B ''spectral'':1A,3B ''spell'':8B ''staggering'':21B ''strik'':15B ''summons'':10B ''target'':17B ''that'':9B ''them'':22B ''to'':14B,29B', 'mage', 'Spectral Arrow is a spell that summons a magical arrow to strike a target, dealing damage and staggering them. You do not know much else about this spell.', '', '', 'spells');
