INSERT INTO public.oghma VALUES ('fortify_spells', 'These magical effects are utility-focused Restoration enchantments that amplify the power of all spells, enhancing their effectiveness regardless of school. This effect is only available on enchanted gear, making it highly coveted by master mages.', '''all'':17B ''amplify'':13B ''are'':6B ''avail'':29B ''by'':37B ''covet'':36B ''effect'':26B ''effectiveness'':21B ''effects'':5B ''enchant'':31B ''enchantments'':11B ''enhancing'':19B ''focus'':9B ''fortify'':1A ''gear'':32B ''highly'':35B ''is'':27B ''it'':34B ''mag'':39B ''magical'':4B ''making'':33B ''mast'':38B ''of'':16B,23B ''on'':30B ''only'':28B ''pow'':15B ''regardless'':22B ''restoration'':10B ''school'':24B ''spells'':2A,18B ''that'':12B ''the'':14B,20B ''thes'':3B ''this'':25B ''utility'':8B ''utility-focus'':7B', 'mage', 'This enchantment makes all your spells stronger, no matter which school of magic they belong to. A mage might know more though.', '', '', 'spells');
