INSERT INTO public.oghma VALUES ('frostbite', 'Frostbite is a Destruction spell that projects a continuous stream of frost, dealing frost damage to health and stamina. It requires a Novice skill level to cast.', '''and'':19B ''cast'':28B ''continuous'':10B ''damag'':16B ''dealing'':14B ''destruction'':5B ''frost'':13B,15B ''frostbit'':1A,2B ''health'':18B ''is'':3B ''it'':21B ''level'':26B ''novic'':24B ''of'':12B ''projects'':8B ''requir'':22B ''skill'':25B ''spell'':6B ''stamin'':20B ''stream'':11B ''that'':7B ''to'':17B,27B', 'mage', 'Frostbite is a spell that releases a continuous stream of frost, freezing enemies and draining their health and stamina. You do not know much else about this spell.', '', '', 'spells');
