INSERT INTO public.oghma VALUES ('healing_hands', 'Healing Hands is a Restoration spell that allows the caster to heal a target by touching them, restoring health over a short period. It requires an Apprentice skill level to cast.', '''allows'':10B ''an'':28B ''apprentic'':29B ''by'':17B ''cast'':12B,33B ''hands'':2A,4B ''heal'':14B ''healing'':1A,3B ''health'':21B ''is'':5B ''it'':26B ''level'':31B ''over'':22B ''period'':25B ''requir'':27B ''restoration'':7B ''restoring'':20B ''short'':24B ''skill'':30B ''spell'':8B ''target'':16B ''that'':9B ''the'':11B ''them'':19B ''to'':13B,32B ''touching'':18B', 'mage', 'Healing Hands is a spell that allows the caster to heal a target by touching them, restoring health over a short period. You do not know much else about this spell.', '', '', 'spells');
