INSERT INTO public.oghma VALUES ('huntsmans_prowess', 'These magical effects are offensive Destruction enchantments that increase damage dealt to animals. This effect is available through custom enchanting and is also found on enchanted items, making it a favored enchantment among hunters.', '''also'':25B ''among'':35B ''and'':23B ''animals'':15B ''are'':6B ''avail'':19B ''custom'':21B ''damag'':12B ''dealt'':13B ''destruction'':8B ''effect'':17B ''effects'':5B ''enchant'':28B ''enchanting'':22B ''enchantment'':34B ''enchantments'':9B ''favor'':33B ''found'':26B ''hunters'':36B ''huntsmans'':1A ''incre'':11B ''is'':18B,24B ''it'':31B ''items'':29B ''magical'':4B ''making'':30B ''offensiv'':7B ''on'':27B ''prowess'':2A ''that'':10B ''thes'':3B ''this'':16B ''through'':20B ''to'':14B', 'mage', 'This enchantment makes weapons stronger against animals, useful for hunters. A mage might know more though.', '', '', 'spells');
