INSERT INTO public.oghma VALUES ('rift_watchtower', 'Rift Watchtower is a small tower located east of Ivarstead and southwest of Clearspring Tarn in the Rift. Occupied by hostile Orc bandits, the tower serves as a minor stronghold for their activities.', '''activiti'':35B ''and'':13B ''as'':29B ''bandits'':25B ''by'':22B ''clearspring'':16B ''east'':10B ''for'':33B ''hostil'':23B ''in'':18B ''is'':5B ''ivarst'':12B ''locat'':9B ''minor'':31B ''occupi'':21B ''of'':11B,15B ''orc'':24B ''rift'':1A,3B,20B ''serv'':28B ''small'':7B ''southwest'':14B ''stronghold'':32B ''tarn'':17B ''the'':19B,26B,34B ''tow'':8B,27B ''watchtow'':2A,4B', 'rift', 'Rift Watchtower is a small tower located east of Ivarstead.You do not know anything else about this area.', 'skyrimall, eastmarch, falkreath', '', 'rift');
