INSERT INTO public.oghma VALUES ('incinerate', 'Incinerate is a Destruction spell that launches a concentrated blast of fire, dealing massive fire damage to a target and incinerating them. It requires an Expert skill level to cast.', '''an'':26B ''and'':21B ''blast'':11B ''cast'':31B ''concentrat'':10B ''damag'':17B ''dealing'':14B ''destruction'':5B ''expert'':27B ''fir'':13B,16B ''incinerat'':1A,2B ''incinerating'':22B ''is'':3B ''it'':24B ''launch'':8B ''level'':29B ''massiv'':15B ''of'':12B ''requir'':25B ''skill'':28B ''spell'':6B ''target'':20B ''that'':7B ''them'':23B ''to'':18B,30B', 'mage', '
