INSERT INTO public.oghma VALUES ('scorpion_fish', 'Scorpion Fish are large brown rough fish found rarely in underground elven areas with an Argonian Fishing Rod. They can be eaten but they have a rather terrible taste.', '''an'':17B ''are'':5B,15B ''argoni'':18B ''be'':23B ''brown'':7B ''but'':25B ''can'':22B ''eat'':24B ''elven'':14B ''fish'':2A,4B,9B ''fishing'':19B ''found'':10B ''hav'':27B ''in'':12B ''larg'':6B ''rarely'':11B ''rath'':29B ''rod'':20B ''rough'':8B ''scorpion'':1A,3B ''tast'':31B ''terribl'':30B ''they'':21B,26B ''underground'':13B ''with'':16B', 'fisher', 'Scorpion Fish are large brown rough fish. They can be eaten but they have a rather terrible taste. ou do not know much more about the fish, but a fisher would.', '', '', 'creatures');
