INSERT INTO public.oghma VALUES ('bolli''s_house', 'Bolli''s House is a small, two-story residence with a cellar, located near the city gates in Riften. Owned by Bolli and his wife Nivenor, it is the first house on the left when entering the city from the north.', '''and'':27B ''bolli'':1A,4B,26B ''by'':25B ''cell'':16B ''city'':20B,42B ''entering'':40B ''first'':34B ''from'':43B ''gat'':21B ''his'':28B ''hous'':3A,6B,35B ''in'':22B ''is'':7B,32B ''it'':31B ''left'':38B ''locat'':17B ''near'':18B ''nivenor'':30B ''north'':45B ''on'':36B ''owned'':24B ''residenc'':13B ''rift'':23B ''s'':2A,5B ''small'':9B ''story'':12B ''the'':19B,33B,37B,41B,44B ''two'':11B ''two-story'':10B ''when'':39B ''wif'':29B ''with'':14B', 'rift', 'Bolli''s House is a small, two-story residence with a cellar, located near the city gates in Riften. You do not know anything else about this area.', 'skyrimall, eastmarch, falkreath', '', 'rift');
