INSERT INTO public.oghma VALUES ('abandoned_prison', 'The Abandoned Prison is a small, desolate Imperial prison located southwest of Windhelm and north-northwest of Fort Amol in Eastmarch. The prison, long out of use, is haunted by the ghosts of prisoners who met their end by drowning when the facility flooded.', '''abandon'':1A,4B ''amol'':22B ''and'':16B ''by'':33B,42B ''desolat'':9B ''drowning'':43B ''eastmarch'':24B ''end'':41B ''facility'':46B ''flood'':47B ''fort'':21B ''ghosts'':35B ''haunt'':32B ''imperial'':10B ''in'':23B ''is'':6B,31B ''locat'':12B ''long'':27B ''met'':39B ''north'':18B ''north-northwest'':17B ''northwest'':19B ''of'':14B,20B,29B,36B ''out'':28B ''prison'':2A,5B,11B,26B ''prisoners'':37B ''small'':8B ''southwest'':13B ''the'':3B,25B,34B,40B,45B ''use'':30B ''when'':44B ''who'':38B ''windhelm'':15B', 'eastmarch, legion', 'The Abandoned Prison is a small, desolate Imperial prison located southwest of Windhelm in Eastmarch.You do not know anything else about this area.', 'skyrimall, pale, rift, winterhold, whiterun', '', 'eastmarch');
