INSERT INTO public.oghma VALUES ('sacellum_of_boethiah', 'The Sacellum of Boethiah is a shrine dedicated to the Daedric Prince Boethiah, located in the mountains east-southeast of Windhelm and south of Traitor''s Post in Eastmarch. There are rumours of dangerous dark rituals taking place here.', '''and'':26B ''are'':35B ''boethiah'':3A,7B,16B ''daedric'':14B ''dangerous'':38B ''dark'':39B ''dedicat'':11B ''east'':22B ''east-southeast'':21B ''eastmarch'':33B ''her'':43B ''in'':18B,32B ''is'':8B ''locat'':17B ''mountains'':20B ''of'':2A,6B,24B,28B,37B ''plac'':42B ''post'':31B ''princ'':15B ''rituals'':40B ''rumours'':36B ''s'':30B ''sacellum'':1A,5B ''shrin'':10B ''south'':27B ''southeast'':23B ''taking'':41B ''the'':4B,13B,19B ''ther'':34B ''to'':12B ''traitor'':29B ''windhelm'':25B', 'eastmarch, daedric, daedra', 'The Sacellum of Boethiah is a shrine dedicated to the Daedric Prince Boethiah, located in the mountains east-southeast of Windhelm in Eastmarch. You do not know anything else about this area.', 'skyrimall, pale, rift, winterhold, whiterun', '', 'eastmarch');
