INSERT INTO public.oghma VALUES ('knifepoint_mine', 'Knifepoint Ridge is a location northwest of Falkreath in Falkreath Hold, positioned southeast of Glenmoril Coven. It serves as a small bandit camp with an iron and corundum mine, known as Knifepoint Mine.', '''an'':27B ''and'':29B ''as'':21B,33B ''bandit'':24B ''camp'':25B ''corundum'':30B ''cov'':18B ''falkreath'':10B,12B ''glenmoril'':17B ''hold'':13B ''in'':11B ''iron'':28B ''is'':5B ''it'':19B ''knifepoint'':1A,3B,34B ''known'':32B ''location'':7B ''min'':2A,31B,35B ''northwest'':8B ''of'':9B,16B ''position'':14B ''ridg'':4B ''serv'':20B ''small'':23B ''southeast'':15B ''with'':26B', 'falkreath', 'Knifepoint Ridge is a location northwest of Falkreath in Falkreath Hold.You do not know anything else about this area.', 'skyrimall, whiterun, rift reach', '', 'falkreath');
