INSERT INTO public.oghma VALUES ('sunderstone_gorge', 'Sunderstone Gorge is a small cave located north-northwest of Falkreath and east of Bilegulch Mine in Falkreath Hold. It is rumored that warlocks have taken over the area.', '''and'':15B ''are'':32B ''bilegulch'':18B ''cav'':8B ''east'':16B ''falkreath'':14B,21B ''gorg'':2A,4B ''hav'':28B ''hold'':22B ''in'':20B ''is'':5B,24B ''it'':23B ''locat'':9B ''min'':19B ''north'':11B ''north-northwest'':10B ''northwest'':12B ''of'':13B,17B ''over'':30B ''rumor'':25B ''small'':7B ''sunderston'':1A,3B ''tak'':29B ''that'':26B ''the'':31B ''warlocks'':27B', 'falkreath', 'Sunderstone Gorge is a small cave located north-northwest of Falkreath in Falkreath Hold.You do not know anything else about this area.', 'skyrimall, whiterun, rift reach', '', 'falkreath');
INSERT INTO public.oghma VALUES ('angi''s_camp', 'Angi''s Camp is a secluded cabin and camp located high in the mountains southeast of Falkreath in Falkreath Hold. The camp is home to Angi, a Nord ranger from Helgen, who lives in hiding after killing two drunken Imperial soldiers responsible for her parents'' deaths.

