INSERT INTO public.oghma VALUES ('dengeir''s_house', 'Dengeir''s House is the residence of Dengeir of Stuhn, the former Jarl and current Thane of Falkreath. It is located in the center of Falkreath, southwest of Corpselight Farm.', '''and'':17B ''cent'':27B ''corpselight'':32B ''current'':18B ''deng'':1A,4B,11B ''falkreath'':21B,29B ''farm'':33B ''form'':15B ''hous'':3A,6B ''in'':25B ''is'':7B,23B ''it'':22B ''jarl'':16B ''locat'':24B ''of'':10B,12B,20B,28B,31B ''residenc'':9B ''s'':2A,5B ''southwest'':30B ''stuhn'':13B ''than'':19B ''the'':8B,14B,26B', 'falkreath', 'Dengeir''s House is the residence of Dengeir of Stuhn, the former Jarl and current Thane of Falkreath.You do not know anything else about this area.', 'skyrimall, whiterun, rift reach', '', 'falkreath');
