INSERT INTO public.oghma VALUES ('gloomreach', 'Gloomreach is a medium-sized cave located southeast of Old Hroldan Inn in the Reach. The cave is inhabited by Falmer.', '''by'':22B ''cav'':8B,19B ''falm'':23B ''gloomreach'':1A,2B ''hrold'':13B ''in'':15B ''inhabit'':21B ''inn'':14B ''is'':3B,20B ''locat'':9B ''medium'':6B ''medium-siz'':5B ''of'':11B ''old'':12B ''reach'':17B ''siz'':7B ''southeast'':10B ''the'':16B,18B', 'reach', 'Gloomreach is a medium-sized cave located southeast of Old Hroldan Inn in the Reach.You do not know anything else about this area.', 'skyrimall, falkreath, whiterun, hjaalmarch, haafingar', '', 'reach');
