INSERT INTO public.oghma VALUES ('old_attius_farm', '
Old Attius Farm is an abandoned Imperial farm located south-southeast of Raven Rock on Solstheim, and north of the Wreck of the Strident Squall. Once a thriving agricultural outpost, the farm has since fallen into disrepair, leaving only remnants of its former use.', '''abandon'':9B ''agricultural'':33B ''an'':8B ''and'':21B ''attius'':2A,5B ''disrep'':41B ''fall'':39B ''farm'':3A,6B,11B,36B ''form'':47B ''imperial'':10B ''into'':40B ''is'':7B ''its'':46B ''leaving'':42B ''locat'':12B ''north'':22B ''of'':16B,23B,26B,45B ''old'':1A,4B ''on'':19B ''once'':30B ''only'':43B ''outpost'':34B ''rav'':17B ''remnants'':44B ''rock'':18B ''sinc'':38B ''solstheim'':20B ''south'':14B ''south-southeast'':13B ''southeast'':15B ''squall'':29B ''strident'':28B ''the'':24B,27B,35B ''thriving'':32B ''use'':48B ''wreck'':25B', 'solstheim', 'You do not know anything about this area.', '', '', 'solstheim');
INSERT INTO public.oghma VALUES ('abandoned_lodge', 'The Abandoned Lodge is a small, secluded shack located north-northeast of Raven Rock on Solstheim. ', '''abandon'':1A,4B ''is'':6B ''locat'':11B ''lodg'':2A,5B ''north'':13B ''north-northeast'':12B ''northeast'':14B ''of'':15B ''on'':18B ''rav'':16B ''rock'':17B ''seclud'':9B ''shack'':10B ''small'':8B ''solstheim'':19B ''the'':3B', 'solstheim', 'You do not know anything about this area.', '', '', 'solstheim');
