INSERT INTO public.oghma VALUES ('bujold''s_retreat', 'Bujold''s Retreat is a camp located east of Thirsk Mead Hall and south-southeast of Skaal Village on Solstheim. The camp is home to a group of Nords who have been exiled from Thirsk Mead Hall after it was taken over by a tribe of rieklings.

Led by Bujold the Unworthy, the Nords at the retreat are determined to reclaim their ancestral hall from the invading rieklings.', '''after'':42B ''ancestral'':67B ''and'':16B ''are'':62B ''at'':59B ''been'':36B ''bujold'':1A,4B,54B ''by'':47B,53B ''camp'':9B,26B ''determin'':63B ''east'':11B ''exil'':37B ''from'':38B,69B ''group'':31B ''hall'':15B,41B,68B ''hav'':35B ''hom'':28B ''invading'':71B ''is'':7B,27B ''it'':43B ''led'':52B ''locat'':10B ''mead'':14B,40B ''nords'':33B,58B ''of'':12B,20B,32B,50B ''on'':23B ''over'':46B ''reclaim'':65B ''retreat'':3A,6B,61B ''rieklings'':51B,72B ''s'':2A,5B ''skaal'':21B ''solstheim'':24B ''south'':18B ''south-southeast'':17B ''southeast'':19B ''tak'':45B ''the'':25B,55B,57B,60B,66B,70B ''thirsk'':13B,39B ''to'':29B,64B ''trib'':49B ''unworthy'':56B ''villag'':22B ''was'':44B ''who'':34B', 'solstheim', 'You do not know anything about this area.', '', '', 'solstheim');
INSERT INTO public.oghma VALUES ('haknir''s_shoal', 'Haknir''s Shoal is a small pirate camp located north-northwest of Skaal Village and east of Benkongerike on Solstheim. The camp is situated along the rugged northern coastline, making it a secluded and strategic hideout for its pirate inhabitants.', '''along'':29B ''and'':19B,38B ''benkongerik'':22B ''camp'':11B,26B ''coastlin'':33B ''east'':20B ''for'':41B ''hakn'':1A,4B ''hideout'':40B ''inhabitants'':44B ''is'':7B,27B ''it'':35B ''its'':42B ''locat'':12B ''making'':34B ''north'':14B ''north-northwest'':13B ''northern'':32B ''northwest'':15B ''of'':16B,21B ''on'':23B ''pirat'':10B,43B ''rugg'':31B ''s'':2A,5B ''seclud'':37B ''shoal'':3A,6B ''situat'':28B ''skaal'':17B ''small'':9B ''solstheim'':24B ''strategic'':39B ''the'':25B,30B ''villag'':18B', 'solstheim', 'You do not know anything about this area.', '', '', 'solstheim');
