INSERT INTO public.oghma VALUES ('frostmoon_crag', 'Frostmoon Crag is a small, secluded camp located under a rock overhang south of Mount Moesring and northeast of the Abandoned Lodge on Solstheim. The camp is inhabited by werewolves, who have created a sanctuary away from the rest of the island''s inhabitants.', '''abandon'':23B ''and'':19B ''away'':38B ''by'':31B ''camp'':9B,28B ''crag'':2A,4B ''creat'':35B ''from'':39B ''frostmoon'':1A,3B ''hav'':34B ''inhabit'':30B ''inhabitants'':46B ''is'':5B,29B ''island'':44B ''locat'':10B ''lodg'':24B ''moesring'':18B ''mount'':17B ''northeast'':20B ''of'':16B,21B,42B ''on'':25B ''overhang'':14B ''rest'':41B ''rock'':13B ''s'':45B ''sanctuary'':37B ''seclud'':8B ''small'':7B ''solstheim'':26B ''south'':15B ''the'':22B,27B,40B,43B ''under'':11B ''werewolv'':32B ''who'':33B', 'solstheim', 'You do not know anything about this area.', '', '', 'solstheim');
