INSERT INTO public.oghma VALUES ('headwaters_of_harstrad', 'The Headwaters of Harstrad are the source of the Harstrad River, located in the northeastern region of Solstheim. The headwaters can be found a short distance downhill to the southeast from the entrance to Benkongerike or by following the river upstream from the Wind Stone, situated to the west-southwest.', '''are'':8B ''be'':25B ''benkongerik'':38B ''by'':40B ''can'':24B ''distanc'':29B ''downhill'':30B ''entranc'':36B ''following'':41B ''found'':26B ''from'':34B,45B ''harstr'':3A,7B,13B ''headwaters'':1A,5B,23B ''in'':16B ''locat'':15B ''northeastern'':18B ''of'':2A,6B,11B,20B ''or'':39B ''region'':19B ''riv'':14B,43B ''short'':28B ''situat'':49B ''solstheim'':21B ''sourc'':10B ''southeast'':33B ''southwest'':54B ''ston'':48B ''the'':4B,9B,12B,17B,22B,32B,35B,42B,46B,51B ''to'':31B,37B,50B ''upstream'':44B ''west'':53B ''west-southwest'':52B ''wind'':47B', 'solstheim', 'You do not know anything about this area.', '', '', 'solstheim');
