INSERT INTO public.oghma VALUES ('edla''s_house', 'Edla''s House is a warm, inviting home located on the north side of Skaal Village, nestled between Wulf Wild-Blood''s House to the southwest and Morwen''s House to the east. This residence is the home of Edla and her son Nikulas, who live a modest but fulfilling life in the village.', '''and'':31B,45B ''betw'':21B ''blood'':25B ''but'':53B ''east'':37B ''edla'':1A,4B,44B ''fulfilling'':54B ''her'':46B ''hom'':11B,42B ''hous'':3A,6B,27B,34B ''in'':56B ''inviting'':10B ''is'':7B,40B ''lif'':55B ''liv'':50B ''locat'':12B ''modest'':52B ''morw'':32B ''nestl'':20B ''nikul'':48B ''north'':15B ''of'':17B,43B ''on'':13B ''residenc'':39B ''s'':2A,5B,26B,33B ''sid'':16B ''skaal'':18B ''southwest'':30B ''the'':14B,29B,36B,41B,57B ''this'':38B ''to'':28B,35B ''villag'':19B,58B ''warm'':9B ''who'':49B ''wild'':24B ''wild-blood'':23B ''wulf'':22B', 'skaal', 'You do not know anything about this area.', '', '', 'solstheim');
